CREATE OR REPLACE FUNCTION public.validate_customer_unit_mode_change()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE snapshot JSONB;
BEGIN
    IF NEW.billing_mode=OLD.billing_mode THEN RETURN NEW; END IF;
    PERFORM niu_lock_customer_unit_mode_change();
    IF NEW.revision<>OLD.revision+1 OR NOT EXISTS (
        SELECT 1 FROM customer_unit_mode_changes e JOIN customer_unit_mode_previews p ON p.id=e.preview_id
        WHERE e.revision=NEW.revision AND e.expected_revision=OLD.revision
          AND e.source_mode=OLD.billing_mode AND e.target_mode=NEW.billing_mode
          AND p.expected_revision=OLD.revision AND p.source_mode=OLD.billing_mode
          AND p.target_mode=NEW.billing_mode AND p.expires_at>clock_timestamp()
          AND p.snapshot->>'blockers_empty'='true' AND p.snapshot->>'change_required'='true'
    ) THEN
        RAISE EXCEPTION 'Billing mode requires an unexpired compatible preview and immutable change record'
            USING ERRCODE='23514',CONSTRAINT='customer_unit_mode_guard';
    END IF;
    snapshot := niu_customer_unit_mode_preview(NEW.billing_mode);
    IF snapshot->>'blockers_empty'<>'true' THEN
        RAISE EXCEPTION 'Customer obligations prevent billing mode change'
            USING ERRCODE='23514',CONSTRAINT='customer_unit_mode_guard';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_customer_payment_reference()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE money_entry UUID; unit_lot UUID;
BEGIN
    IF TG_TABLE_NAME='customer_funding_receipts' THEN money_entry:=NEW.entry_id;
    ELSE unit_lot:=NEW.unit_lot_id; END IF;
    INSERT INTO customer_payment_references(channel,payment_reference,entry_id,unit_lot_id,created_at)
        VALUES(NEW.channel,NEW.payment_reference,money_entry,unit_lot,NEW.created_at)
        ON CONFLICT(channel,payment_reference) DO NOTHING;
    IF NOT EXISTS (SELECT 1 FROM customer_payment_references r
        WHERE r.channel=NEW.channel AND r.payment_reference=NEW.payment_reference
            AND r.entry_id IS NOT DISTINCT FROM money_entry AND r.unit_lot_id IS NOT DISTINCT FROM unit_lot) THEN
        RAISE EXCEPTION 'Payment reference already belongs to a different funding target'
            USING ERRCODE='23514', CONSTRAINT='customer_payment_reference_target';
    END IF;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_customer_unit_key_limit()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF TG_OP = 'DELETE' THEN
        RAISE EXCEPTION 'Credits key spending limits cannot be deleted' USING ERRCODE = '23514';
    END IF;
    PERFORM organization_id FROM customer_unit_accounts WHERE organization_id = NEW.organization_id FOR NO KEY UPDATE;
    IF NOT EXISTS (
        SELECT 1 FROM api_keys k
        WHERE k.organization_id = NEW.organization_id
          AND k.project_id = NEW.project_id
          AND k.id = NEW.spending_root_id
          AND k.spending_root_id = NEW.spending_root_id
    ) THEN
        RAISE EXCEPTION 'Credits key spending limit must target a root spending identity'
            USING ERRCODE = '23514';
    END IF;
    IF (TG_OP = 'INSERT' AND NEW.revision <> 1)
       OR (TG_OP = 'UPDATE' AND (
            NEW.revision <> OLD.revision + 1
            OR ROW(NEW.organization_id, NEW.project_id, NEW.spending_root_id)
               IS DISTINCT FROM ROW(OLD.organization_id, OLD.project_id, OLD.spending_root_id)
       ))
       OR NOT EXISTS (
            SELECT 1 FROM customer_unit_key_limit_history h
            WHERE h.organization_id = NEW.organization_id
              AND h.project_id = NEW.project_id
              AND h.spending_root_id = NEW.spending_root_id
              AND h.revision = NEW.revision
              AND h.definition_revision = NEW.definition_revision
              AND h.limit_atoms IS NOT DISTINCT FROM NEW.limit_atoms
       ) THEN
        RAISE EXCEPTION 'Credits key spending limit requires a matching sequential history revision'
            USING ERRCODE = '23514';
    END IF;
    IF NEW.limit_atoms IS NOT NULL THEN
        IF EXISTS (
            SELECT 1 FROM customer_unit_reservations r
            WHERE r.organization_id = NEW.organization_id
              AND r.project_id = NEW.project_id
              AND niu_customer_attempt_spending_root(r.attempt_id) IS NULL
              AND NOT EXISTS (
                  SELECT 1 FROM customer_unit_resolutions s
                  WHERE s.attempt_id = r.attempt_id AND s.kind = 'release'
              )
        ) THEN
            RAISE EXCEPTION 'Unattributed Credits liabilities require reconciliation before setting a key limit'
                USING ERRCODE = '23514';
        END IF;
        IF niu_customer_unit_key_committed(NEW.organization_id, NEW.project_id, NEW.spending_root_id) > NEW.limit_atoms THEN
            RAISE EXCEPTION 'Credits key spending limit is below committed liability'
                USING ERRCODE = '23514', CONSTRAINT = 'customer_unit_key_limit_below_committed';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

