        END IF;
    ELSE
        IF EXISTS (SELECT 1 FROM personal_attempt_routes WHERE attempt_id = NEW.attempt_id) THEN
            RAISE EXCEPTION 'customer media pricing conflicts with personal route' USING ERRCODE = '23514';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

