CREATE OR REPLACE FUNCTION public.niu_invalidate_supplier_route_qualification()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
DECLARE affected RECORD;
BEGIN
    IF niu_authorized_encryption_rewrap(
        TG_TABLE_NAME, 'credential_ciphertext', to_jsonb(OLD), to_jsonb(NEW)
    ) THEN RETURN NEW; END IF;
    FOR affected IN
        UPDATE provider_offers
           SET active = FALSE, current_qualification_review = NULL, current_authorization = NULL
         WHERE vendor_id = OLD.id
           AND (current_qualification_review IS NOT NULL OR current_authorization IS NOT NULL)
        RETURNING provider_id, id
    LOOP
        INSERT INTO provider_audit_events(provider_id, action, resource_id)
        VALUES (affected.provider_id, 'route_qualification_invalidated', affected.id);
    END LOOP;
    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_retained_video_composer_draft()
 RETURNS trigger
 LANGUAGE plpgsql
AS $function$
BEGIN
    IF OLD.payload IS NOT NULL AND OLD.expires_at>clock_timestamp() THEN
        RAISE EXCEPTION 'retained Video composer content protects its workspace'
            USING ERRCODE='23503';
    END IF;
    RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.preserve_video_input_public_reference()
